using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;
using STP.Application;
using STP.Infrastructure.Persistence;
using STP.Infrastructure.Content;
using STP.Puzzle.Domain;
using STP.Puzzle.Solver;

namespace STP.Tools.HumanReadback;

// These are adversarial AUTOMATED fixtures. A forged PARTICIPANT_UI label must never attest a human.
internal static class SelfTests
{
    internal static int Run(SourceBundle sources,string scratch)
    {
        scratch=Path.GetFullPath(scratch);SourceBundle.Need(!Directory.Exists(scratch),"SELF_TEST_OUTPUT_EXISTS");Directory.CreateDirectory(scratch);int cases=0,asserts=0;var results=new List<object>();
        void Check(bool ok,string message){asserts++;if(!ok)throw new InvalidOperationException("SELF_TEST_FAILED:"+message);}
        void Case(string name,Action body){body();cases++;results.Add(new{name,result="Passed"});}
        var catalog=sources.Catalogs.Values.OrderBy(c=>c.StudyId,StringComparer.Ordinal).First(c=>c.Assignments[0].Purpose==HumanAssignmentPurpose.CAMPAIGN_TIME);var assignment=catalog.Assignments[0];var puzzle=assignment.Puzzle;var view=new Public240ReviewSession(puzzle);var solved=PuzzleSolver.Solve(puzzle.ToDomainDefinition(),new SolverLimits(1000000,10000));Check(solved.Classification==SolverClassification.UNIQUE,"Actual controlled fixture solver");long now=10;
        Direction Toward(CellCoordinate a,CellCoordinate b)=>b.X>a.X?Direction.E:b.X<a.X?Direction.W:b.Y>a.Y?Direction.S:Direction.N;
        for(int i=0;i<solved.Path.Count;i++){var c=solved.Path[i];int ports=(1<<(int)(i==0?puzzle.ToDomainDefinition().A.Side:Toward(c,solved.Path[i-1])))|(1<<(int)(i==solved.Path.Count-1?puzzle.ToDomainDefinition().B.Side:Toward(c,solved.Path[i+1])));var shape=Enumerable.Range(0,6).Single(s=>TrackGeometry.Ports((TrackShape)s)==ports);Check(view.Apply(c.X,c.Y,(DevelopmentTool)(shape+3),now)==DevelopmentCommandStatus.Applied,"Actual Domain track command");now+=10;}
        var checkpoint=view.CaptureHumanCheckpoint(now);Check(checkpoint.Phase==SessionPhase.SolvedPendingCommit,"Actual Domain completion");
        HumanTrialRecord Trial(HumanFirstContact? contact=HumanFirstContact.NEVER_SEEN,bool old=false,bool prior=false,bool interrupted=false,bool timing=true,long? preview=5,HumanExposureState exposure=HumanExposureState.EXPOSURE_CONFIRMED,HumanTrialOutcome outcome=HumanTrialOutcome.SOLVED_UNREVIEWED,IReadOnlyList<HumanHintObservation>? hints=null)=>new(assignment.Id,puzzle.Identity,assignment.SourceSha256,Guid.NewGuid(),exposure,contact,old,prior,interrupted,Guid.NewGuid(),exposure==HumanExposureState.EXPOSURE_CONFIRMED?0:null,preview,timing,outcome,checkpoint,hints??Array.Empty<HumanHintObservation>());
        byte[] Bytes(HumanTrialRecord trial,HumanRunOrigin origin=HumanRunOrigin.AUTOMATED_TEST,string? token=null,long generation=1)=>new HumanCalibrationCodec(sources.Json,catalog).Encode(new HumanObservationSnapshot(generation,new HumanCalibrationRun(catalog.ManifestBytesSha256,token??Guid.NewGuid().ToString("N"),origin,"2026-10-21T00:00:00Z",0,new[]{trial})));
        Readback Read(params byte[][] inputs){var r=new Readback(sources);for(int i=0;i<inputs.Length;i++)r.Add(Path.Combine(scratch,"controlled-fixture-"+i+".json"),inputs[i]);r.ClassifyDuplicates();return r;}
        Case("AUTOMATED_TEST is always separate",()=>{var r=Read(Bytes(Trial()));Check(r.Rows.Single().Reasons.Contains("AUTOMATED_TEST_ORIGIN"),"Automation exclusion");});
        Case("Forged ParticipantUI/self-report remains unattested",()=>{var r=Read(Bytes(Trial(),HumanRunOrigin.PARTICIPANT_UI));var row=r.Rows.Single();Check(row.Reasons.Count==0,"Controlled complete raw observations");Check(!row.HumanIdentityAttested&&!row.DeviceAccepted&&!row.CalibrationApproved&&!row.PromotionAllowed&&row.ExternalReviewerRequired,"No automatic attestation");Check(row.ObservedActiveElapsedMs==checkpoint.ActiveElapsedMs&&row.ObservedPreviewActiveMs==5,"Only actual controlled Domain/checkpoint values");});
        foreach(var contact in new[]{HumanFirstContact.SEEN_OR_PLAYED,HumanFirstContact.UNSURE})Case("Contact "+contact,()=>Check(Read(Bytes(Trial(contact),HumanRunOrigin.PARTICIPANT_UI)).Rows.Single().Reasons.Count>0,"Seen/unsure separate"));
        Case("Missing contact",()=>Check(Read(Bytes(Trial(null),HumanRunOrigin.PARTICIPANT_UI)).Rows.Single().Reasons.Contains("FIRST_CONTACT_NOT_RECORDED"),"Contact missing"));
        Case("Prior version",()=>Check(Read(Bytes(Trial(old:true),HumanRunOrigin.PARTICIPANT_UI)).Rows.Single().Reasons.Contains("SELF_REPORTED_PRIOR_VERSION"),"Version exclusion"));
        Case("Prior exposure",()=>Check(Read(Bytes(Trial(prior:true),HumanRunOrigin.PARTICIPANT_UI)).Rows.Single().Reasons.Contains("PRIOR_OR_POSSIBLE_EXPOSURE"),"Repeat exclusion"));
        Case("Interrupted/missing preview",()=>{var r=Read(Bytes(Trial(interrupted:true,timing:false,preview:null),HumanRunOrigin.PARTICIPANT_UI));Check(r.Rows.Single().Reasons.Contains("INTERRUPTED")&&r.Rows.Single().Reasons.Contains("TIMING_INCOMPLETE_OR_PREVIEW_MISSING"),"Interrupted times not reconstructed");Check(r.Rows.Single().ObservedPreviewActiveMs==null,"No invented preview");});
        Case("Possible exposure",()=>Check(Read(Bytes(Trial(exposure:HumanExposureState.UNCERTAIN),HumanRunOrigin.PARTICIPANT_UI)).Rows.Single().Reasons.Contains("EXPOSURE_UNCONFIRMED_OR_UNCERTAIN"),"Uncertain exposure"));
        Case("Pending hint remains separate",()=>{var hint=new HumanHintObservation(Guid.NewGuid(),checkpoint.Revision,0,0,"CONTROLLED_POSSIBLE_HINT",CellContent.MARK_EMPTY,HumanHintState.HINT_DISPLAY_PENDING);var r=Read(Bytes(Trial(hints:new[]{hint}),HumanRunOrigin.PARTICIPANT_UI));Check(r.Rows.Single().Reasons.Contains("CONFIRMED_OR_POSSIBLE_HINT_ASSISTANCE")&&r.Rows.Single().Reasons.Contains("HINT_DISPLAY_PENDING_OR_UNCERTAIN"),"Pending is not free or unassisted");});
        Case("Unsolved outcome never becomes timing candidate",()=>Check(Read(Bytes(Trial(outcome:HumanTrialOutcome.ABORTED),HumanRunOrigin.PARTICIPANT_UI)).Rows.Single().Reasons.Contains("NOT_SOLVED"),"Outcome exclusion"));
        Case("Byte-identical copies count once",()=>{var b=Bytes(Trial(),HumanRunOrigin.PARTICIPANT_UI);var r=Read(b,b);Check(r.Inputs.Count==2&&r.Inputs[1].DuplicateOf!=null&&r.Rows.Count==1,"Exact duplicate deweighted");});
        Case("Multiple session exports never auto-select newest",()=>{string token=Guid.NewGuid().ToString("N");var trial=Trial();var r=Read(Bytes(trial,HumanRunOrigin.PARTICIPANT_UI,token,1),Bytes(trial,HumanRunOrigin.PARTICIPANT_UI,token,2));Check(r.Rows.Count==2&&r.Rows.All(x=>x.Reasons.Contains("SESSION_HAS_MULTIPLE_EXPORTS_OR_CONFLICT")),"No generation preference");});
        Case("Reused trial/exposure across tokens is detected",()=>{var trial=Trial();var r=Read(Bytes(trial,HumanRunOrigin.PARTICIPANT_UI),Bytes(trial,HumanRunOrigin.PARTICIPANT_UI));Check(r.Rows.All(x=>x.Reasons.Contains("TRIAL_ID_REUSED_ACROSS_RECORDS")&&x.Reasons.Contains("EXPOSURE_ID_REUSED_ACROSS_TRIALS_OR_RECORDS")),"Cloned identities separate");});
        Case("Actual restart history stays repeated and retains possible assistance",()=>{var empty=new Public240ReviewSession(puzzle).CaptureHumanCheckpoint(0);var priorHint=new HumanHintObservation(Guid.NewGuid(),empty.Revision,0,0,"CONTROLLED_UNCERTAIN_HISTORY",CellContent.MARK_EMPTY,HumanHintState.UNCERTAIN);var first=new HumanTrialRecord(assignment.Id,puzzle.Identity,assignment.SourceSha256,Guid.NewGuid(),HumanExposureState.EXPOSURE_CONFIRMED,HumanFirstContact.NEVER_SEEN,false,false,false,Guid.NewGuid(),0,5,true,HumanTrialOutcome.ABORTED,empty,new[]{priorHint});var run=new HumanCalibrationRun(catalog.ManifestBytesSha256,Guid.NewGuid().ToString("N"),HumanRunOrigin.PARTICIPANT_UI,"2026-10-21T00:00:00Z",0,new[]{first,Trial(prior:true)});var r=Read(new HumanCalibrationCodec(sources.Json,catalog).Encode(new HumanObservationSnapshot(1,run)));Check(r.Rows.Count==2&&r.Rows.All(x=>x.Reasons.Contains("REPEATED_PUZZLE_WITHIN_RUN")),"Restart is not a fresh puzzle");Check(r.Rows.All(x=>x.HintSlotsAcrossRunPuzzleHistory==1&&x.Reasons.Contains("HINT_ASSISTANCE_IN_RUN_PUZZLE_HISTORY")),"An empty new-attempt hint list cannot erase earlier possible influence");});
        Case("Rehashed missing assignment prefix is rejected by actual codec",()=>{var root=SourceBundle.Parse(Bytes(Trial()));var payload=SourceBundle.Get(root,"payload");var altered=JsonValue.CreateObject(payload.Members.Select(m=>m.Name=="nextAssignmentIndex"?new JsonMember(m.Name,JsonValue.CreateInteger(2)):m));var payloadBytes=JcsSerializer.Serialize(altered).Utf8!;var envelope=JsonValue.CreateObject(root.Members.Select(m=>m.Name=="payload"?new JsonMember(m.Name,altered):m.Name=="payloadSha256"?new JsonMember(m.Name,JsonValue.CreateString(SourceBundle.Hash(payloadBytes))):m));var r=Read(JcsSerializer.Serialize(envelope).Utf8!);Check(r.Rows.Count==0&&r.Inputs.Single().Rejection!=null,"Prefix guard, not envelope hash, rejects the record");});
        foreach(var mutation in new[]{"source","payload","extra","duplicate-key","game-save"})Case("Rejected record "+mutation,()=>{string text=Encoding.UTF8.GetString(Bytes(Trial()));text=mutation switch{"source"=>text.Replace(catalog.UiSourceSha256,new string('0',64)),"payload"=>text.Replace("\"payloadSha256\":\"","\"payloadSha256\":\"0"),"extra"=>text.Replace("\"humanRecordVersion\":1","\"humanRecordVersion\":1,\"ledger\":{}"),"duplicate-key"=>text.Replace("\"humanRecordVersion\":1","\"humanRecordVersion\":1,\"humanRecordVersion\":1"),_=>"{\"recordVersion\":3,\"profile\":{}}"};var r=Read(Encoding.UTF8.GetBytes(text));Check(r.Inputs.Single().Rejection!=null&&r.Rows.Count==0,"Bad record retained/rejected");});
        void BadBundle(string name,Action<string> mutate)
        {
            string dir=Path.Combine(scratch,name);Directory.CreateDirectory(dir);foreach(var p in sources.Provenance){string file=p.Key.StartsWith("manifest-",StringComparison.Ordinal)?p.Key.Substring(9):p.Key switch{"raw-lock"=>"raw-sha256-lock.json","ui-source-lock"=>"ui-source-lock.json",_=>p.Key+".json"};File.WriteAllBytes(Path.Combine(dir,file),p.Value);}mutate(dir);bool rejected=false;try{_=new SourceBundle(sources.Root,dir,Path.Combine(dir,"public-catalog.json"),Path.Combine(dir,"public-bindings.json"),Path.Combine(dir,"producer-source-bindings.json"));}catch(ArgumentException){rejected=true;}Check(rejected,"Adversarial source bundle must stop: "+name);
        }
        Case("Raw lock UI hash mutation",()=>BadBundle("bad-ui",d=>{string p=Path.Combine(d,"raw-sha256-lock.json");File.WriteAllText(p,File.ReadAllText(p).Replace(catalog.UiSourceSha256,new string('0',64)));}));
        Case("Unknown raw lock version",()=>BadBundle("bad-version",d=>{string p=Path.Combine(d,"raw-sha256-lock.json");File.WriteAllText(p,File.ReadAllText(p).Replace("\"schemaVersion\":1","\"schemaVersion\":2"));}));
        Case("Manifest bytes lock mutation",()=>BadBundle("bad-manifest",d=>{string p=Directory.GetFiles(d,"campaign-pack-*.json").First();File.AppendAllText(p," ");}));
        Case("Source identity mutation",()=>BadBundle("bad-source",d=>{string p=Path.Combine(d,"producer-source-bindings.json");File.WriteAllText(p,File.ReadAllText(p).Replace(assignment.SourceSha256,new string('0',64)));}));
        var original=Bytes(Trial());var archive=Read(original,original);archive.Write(Path.Combine(scratch,"controlled-originals-readback"));Case("Original bytes preserved; output refuses overwrite",()=>{Check(File.ReadAllBytes(Path.Combine(scratch,"controlled-originals-readback","original-exports",SourceBundle.Hash(original)+".json")).SequenceEqual(original),"Original bytes");bool refused=false;try{archive.Write(Path.Combine(scratch,"controlled-originals-readback"));}catch(ArgumentException){refused=true;}Check(refused,"No report overwrite");});
        Case("Same inputs produce identical readback bytes",()=>{archive.Write(Path.Combine(scratch,"controlled-repeat-readback"));Check(File.ReadAllBytes(Path.Combine(scratch,"controlled-originals-readback","readback.internal.json")).SequenceEqual(File.ReadAllBytes(Path.Combine(scratch,"controlled-repeat-readback","readback.internal.json"))),"Deterministic report; no wallclock or random output metadata");});
        Case("Rejected original export bytes remain archived",()=>{byte[] bad=Encoding.UTF8.GetBytes("{\"recordVersion\":3,\"profile\":{}}");var rejected=Read(bad);rejected.Write(Path.Combine(scratch,"controlled-rejected-readback"));Check(rejected.Inputs.Single().Rejection!=null&&rejected.Rows.Count==0,"Rejected save cannot become a Human observation");Check(File.ReadAllBytes(Path.Combine(scratch,"controlled-rejected-readback","original-exports",SourceBundle.Hash(bad)+".json")).SequenceEqual(bad),"Rejected original preserved exactly");});
        Case("One actual six-case automated export remains fully separate",()=>
        {
            var trials=new List<HumanTrialRecord>();var epoch=Guid.NewGuid();foreach(var item in catalog.Assignments)
            {
                var input=item.Puzzle;var definition=input.ToDomainDefinition();var actual=new Public240ReviewSession(input);var result=PuzzleSolver.Solve(definition,new SolverLimits(1000000,10000));Check(result.Classification==SolverClassification.UNIQUE,"Six-case actual solver");long at=10;
                for(int i=0;i<result.Path.Count;i++){var c=result.Path[i];int ports=(1<<(int)(i==0?definition.A.Side:Toward(c,result.Path[i-1])))|(1<<(int)(i==result.Path.Count-1?definition.B.Side:Toward(c,result.Path[i+1])));int shape=Enumerable.Range(0,6).Single(s=>TrackGeometry.Ports((TrackShape)s)==ports);Check(actual.Apply(c.X,c.Y,(DevelopmentTool)(shape+3),at)==DevelopmentCommandStatus.Applied,"Six-case actual Domain command");at+=10;}
                var cp=actual.CaptureHumanCheckpoint(at);Check(cp.Phase==SessionPhase.SolvedPendingCommit,"Six-case actual completion");trials.Add(new HumanTrialRecord(item.Id,input.Identity,item.SourceSha256,Guid.NewGuid(),HumanExposureState.EXPOSURE_CONFIRMED,HumanFirstContact.NEVER_SEEN,false,false,false,epoch,0,5,true,HumanTrialOutcome.SOLVED_UNREVIEWED,cp,Array.Empty<HumanHintObservation>()));
            }
            var run=new HumanCalibrationRun(catalog.ManifestBytesSha256,Guid.NewGuid().ToString("N"),HumanRunOrigin.AUTOMATED_TEST,"2026-10-21T00:00:00Z",catalog.Assignments.Count,trials);byte[] bytes=new HumanCalibrationCodec(sources.Json,catalog).Encode(new HumanObservationSnapshot(1,run));var r=Read(bytes);Check(r.Rows.Count==6&&r.Rows.All(row=>row.RunComplete&&row.Reasons.Contains("AUTOMATED_TEST_ORIGIN")),"Six-case separate observations");string exportDir=Path.Combine(scratch,"controlled-six-case-exports");Directory.CreateDirectory(exportDir);File.WriteAllBytes(Path.Combine(exportDir,"automated-six-case.json"),bytes);
        });
        File.WriteAllText(Path.Combine(scratch,"self-test-result.json"),JsonSerializer.Serialize(new{evidenceKind="CONTROLLED_ADVERSARIAL_AUTHORING_TESTS",cases,asserts,results,actualHumanEvidence=false,actualDeviceEvidence=false,humanAcceptance=false,promotionAllowed=false},new JsonSerializerOptions{WriteIndented=true})+"\n");Console.WriteLine($"Controlled authoring fixtures PASS: {cases} cases, {asserts} assertions. No Human or device evidence.");return 0;
    }
}
